  "filename": "script.js",
  "content": "(() => {
  // Utility: simple fetch wrapper for the API
  const apiRequest = async (method, path, data = null) => {
    const options = {
      method: method,
      headers: {
        'Content-Type': 'application/json'
      }
    };
    if (data !== null) {
      options.body = JSON.stringify(data);
    }
    const resp = await fetch(`/api${path}`, options);
    const json = await resp.json().catch(() => ({}));
    if (!resp.ok) {
      const err = new Error(json.error || resp.statusText);
      err.status = resp.status;
      err.body = json;
      throw err;
    }
    return json;
  };

  // Toast notification system
  const toastContainer = document.createElement('div');
  toastContainer.id = 'toast-container';
  toastContainer.style.position = 'fixed';
  toastContainer.style.bottom = '1rem';
  toastContainer.style.right = '1rem';
  toastContainer.style.zIndex = '1000';
  document.body.appendChild(toastContainer);

  const showToast = (msg, type = 'info', duration = 3000) => {
    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    toast.textContent = msg;
    toast.style.minWidth = '200px';
    toast.style.marginTop = '0.5rem';
    toast.style.padding = '0.75rem 1rem';
    toast.style.borderRadius = '4px';
    toast.style.boxShadow = '0 2px 6px rgba(0,0,0,0.2)';
    toast.style.background = type === 'error' ? '#ff4d4f' : '#1890ff';
    toast.style.color = '#fff';
    toastContainer.appendChild(toast);
    setTimeout(() => toastContainer.removeChild(toast), duration);
  };

  // Theme handling (light/dark) using CSS variables defined in style.css
  const themeToggle = document.getElementById('theme-toggle');
  const setTheme = (theme) => {
    document.documentElement.dataset.theme = theme;
    localStorage.setItem('theme', theme);
  };
  const initTheme = () => {
    const saved = localStorage.getItem('theme') || 'light';
    setTheme(saved);
  };
  themeToggle?.addEventListener('click', () => {
    const next = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
    setTheme(next);
  });
  initTheme();

  // Sidebar active link handling
  const updateSidebarActive = (slug) => {
    document.querySelectorAll('#sidebar .nav-item').forEach(link => {
      const href = link.getAttribute('href');
      if (href === `#/${slug}`) {
        link.classList.add('active');
        link.setAttribute('aria-current', 'page');
      } else {
        link.classList.remove('active');
        link.removeAttribute('aria-current');
      }
    });
  };

  // Page registry and navigation controller
  window.ForgeAI = {
    _pages: {},
    registerPage(slug, renderer) {
      this._pages[slug] = renderer;
    },
    navigate(slug) {
      window.location.hash = `#/${slug}`;
    }
  };

  const renderPage = async (slug) => {
    const root = document.getElementById('content');
    const pageTitleEl = document.getElementById('page-title');
    const renderer = ForgeAI._pages[slug];
    if (!renderer) {
      root.innerHTML = `<div class="error">Page "${slug}" not found.</div>`;
      pageTitleEl.textContent = 'Error';
      return;
    }
    updateSidebarActive(slug);
    pageTitleEl.textContent = slug.charAt(0).toUpperCase() + slug.slice(1);
    // Provide a simple context object
    const ctx = {
      root,
      api: apiRequest,
      showToast,
      search: document.getElementById('global-search')?.value || ''
    };
    try {
      await renderer(ctx);
    } catch (e) {
      console.error(e);
      showToast(e.message || 'Unexpected error', 'error');
      root.innerHTML = `<div class="error">${e.message || 'Error'}</div>`;
    }
  };

  // Router – reacts to hash changes and initial load
  const onHashChange = () => {
    const hash = window.location.hash || '#/dashboard';
    const slug = hash.replace(/^#\//, '').split('?')[0];
    renderPage(slug);
  };
  window.addEventListener('hashchange', onHashChange);
  window.addEventListener('load', onHashChange);

  // ---- Default page renderers ------------------------------------------------

  // Dashboard renderer – shows KPI cards and a simple chart
  ForgeAI.registerPage('dashboard', async ({ root, api, showToast }) => {
    root.innerHTML = `
      <section class="dashboard">
        <div class="kpi-grid" id="kpi-grid"></div>
        <div class="chart-container" style="margin-top:1rem;">
          <canvas id="tasks-chart" width="400" height="200"></canvas>
        </div>
        <div class="recent-activity" style="margin-top:1rem;">
          <h2>Recent Activity</h2>
          <ul id="recent-list"></ul>
        </div>
      </section>`;
    const kpiGrid = document.getElementById('kpi-grid');
    const recentList = document.getElementById('recent-list');
    const canvas = document.getElementById('tasks-chart');
    const ctx = canvas.getContext('2d');

    // Load tasks and compute KPIs
    let tasks = [];
    try {
      const resp = await api('GET', '/tasks');
      tasks = resp.tasks || [];
    } catch (e) {
      showToast('Failed to load tasks for dashboard', 'error');
    }
    const total = tasks.length;
    const completed = tasks.filter(t => t.completed).length;
    const pending = total - completed;
    const overdue = tasks.filter(t => !t.completed && new Date(t.due_date) < new Date()).length;

    kpiGrid.innerHTML = `
      <div class="kpi-card"><h3>Total Tasks</h3><p>${total}</p></div>
      <div class="kpi-card"><h3>Completed</h3><p>${completed}</p></div>
      <div class="kpi-card"><h3>Pending</h3><p>${pending}</p></div>
      <div class="kpi-card"><h3>Overdue</h3><p>${overdue}</p></div>`;

    // Simple bar chart for tasks per priority
    const priorities = ['Low', 'Medium', 'High'];
    const counts = priorities.map(p => tasks.filter(t => t.priority === p).length);
    const maxCount = Math.max(...counts, 1);
    const barWidth = 80;
    const gap = 30;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--accent-colour') || '#336699';
    counts.forEach((cnt, i) => {
      const x = gap + i * (barWidth + gap);
      const barHeight = (cnt / maxCount) * (canvas.height - 40);
      const y = canvas.height - barHeight - 20;
      ctx.fillRect(x, y, barWidth, barHeight);
      ctx.fillStyle = '#000';
      ctx.textAlign = 'center';
      ctx.fillText(priorities[i], x + barWidth / 2, canvas.height - 5);
      ctx.fillStyle = getComputedStyle(document.documentElement).getPropertyValue('--accent-colour') || '#336699';
    });

    // Recent activity – last 5 modified/created tasks (using created_at if present, else fallback to due_date)
    const recent = tasks
      .sort((a, b) => new Date(b.due_date) - new Date(a.due_date))
      .slice(0, 5);
    recentList.innerHTML = recent.map(t => `<li>${t.title} – ${t.completed ? '✅ Completed' : '⏳ Pending'}</li>`).join('') || '<li>No recent activity.</li>';
  });

  // Settings renderer – placeholder (future profile persistence)
  ForgeAI.registerPage('settings', async ({ root, api, showToast }) => {
    root.innerHTML = `
      <section class="settings">
        <h2>Settings</h2>
        <p>Profile settings will be added soon.</p>
      </section>`;
  });

  // Tasks entity page – placeholder registration (actual implementation will be injected by other generated files)
  ForgeAI.registerPage('tasks', async ({ root, api, showToast }) => {
    root.innerHTML = `<div class="placeholder">Loading Tasks module…</div>`;
  });
})();
"
}
